"""Private owner-authorised IAM/S3 isolated commerce writer acceptance only.

No customer data, external email, checkout, source medicine rights or live producer cutover.
This handler must remain AWS-invoke-only, without Function URL or API Gateway.
"""
import datetime
import hashlib
import json
import os
import re
import uuid

import boto3
from botocore.exceptions import ClientError

BUCKET = os.environ["EVIDENCE_BUCKET"]
BASE = "commerce/owner-attestations/_isolation-probes/"
NOT_COMMERCE = "intelligence/_isolation-probes/"
S3 = boto3.client("s3", region_name="eu-north-1")

def _put(key, body):
    raw = json.dumps(body, separators=(",", ":"), sort_keys=True).encode("utf-8")
    response = S3.put_object(
        Bucket=BUCKET, Key=key, Body=raw, ContentType="application/json",
        ServerSideEncryption="AES256", IfNoneMatch="*",
        Metadata={"evidence-type": "private-security-canary", "customer-data": "false"},
    )
    return {"key": key, "sha256": hashlib.sha256(raw).hexdigest(), "etag": response.get("ETag")}

def handler(event, context):
    if not isinstance(event, dict) or event.get("operation") != "verify-isolation":
        return {"passed": False, "code": "not_authorized_canary_operation"}
    if set(event) != {"operation", "review_ticket"}:
        return {"passed": False, "code": "unexpected_event_fields"}
    ticket = event.get("review_ticket")
    if not isinstance(ticket, str) or not re.fullmatch(r"[A-Za-z0-9_.:-]{8,72}", ticket):
        return {"passed": False, "code": "invalid_review_ticket"}
    nonce = uuid.uuid4().hex
    at = datetime.datetime.now(datetime.timezone.utc).isoformat()
    evidence = {
        "schema": "novapharm.security.commerce_writer_canary.v1",
        "generated_at_utc": at,
        "source": "isolated-invocation-no-public-endpoint",
        "review_ticket": ticket,
        "customer_data": False,
        "medicine_data": False,
        "sales_transactions": 0,
        "production_release_accepted": False,
    }
    # Prove a commerce writer cannot cross into the separate Intelligence namespace.
    bad_key = NOT_COMMERCE + nonce + ".json"
    try:
        _put(bad_key, evidence)
    except ClientError as error:
        if error.response.get("Error", {}).get("Code") != "AccessDenied":
            return {"passed": False, "code": "unexpected_forbidden_write_error",
                    "aws_error": error.response.get("Error", {}).get("Code", "unknown")}
    else:
        return {"passed": False, "code": "FORBIDDEN_CROSS_WORKLOAD_WRITE_SUCCEEDED",
                "unexpected_object": bad_key}
    good_key = BASE + nonce + ".json"
    try:
        accepted = _put(good_key, evidence)
    except ClientError as error:
        return {"passed": False, "code": "authorized_commerce_write_failed",
                "aws_error": error.response.get("Error", {}).get("Code", "unknown")}
    return {"passed": True, "code": "isolated_writer_contract_verified",
            "authorized_key": accepted["key"], "authorized_sha256": accepted["sha256"],
            "forbidden_cross_workload": "AccessDenied",
            "production_exporter_cutover": False, "customer_access_enabled": False}
